result=[]
for n,(title,pages,q,goal,args) in enumerate(units,1):
 aa=[]
 for i,(speaker,claim,reason,warrant,kind,limit,check) in enumerate(args):
  aa.append(dict(id=f'A{(n-1)*4+i+1:03}',speaker=speaker,claim=claim,reason=reason,warrant=warrant,kind=kind,limit=limit,check=check,pages=pages))
 result.append(dict(id=n,title=title,pages=pages,question=q,goal=goal,arguments=aa))
(p/'assets/content.js').write_text('window.BUYX_UNITS='+json.dumps(result,ensure_ascii=False)+';\n')
(p/'ARGUMENTATLAS.md').write_text('# Medizin / Denken – Argumentatlas\n\nEigene sinngemässe Rekonstruktionen. Fundstellen: Seiten der bereitgestellten bereinigten Lesefassung, DIE ZEIT, 21.10.2026. Ergänzte Schlussregeln sind Interpretationen, keine Zitate.\n\n'+'\n\n'.join(f'## {u["id"]}. {u["title"]} · S. {u["pages"]}\n\n'+'\n\n'.join(f'### {a["id"]} · {a["speaker"]} · {a["kind"]}\n\nThese: {a["claim"]}\n\nGrund: {a["reason"]}\n\nErgänzte Schlussregel: {a["warrant"]}\n\nPrüfpunkt: {a["limit"]}\n\nFrage: {a["check"]}' for a in u['arguments']) for u in result))
